 static void AddItem(Offline70EconomyState s,uint item,uint count){Offline70EconomyItemDefinition d=Definition(item);if(count==0||count>1000000)throw new InvalidDataException("Economy grant count");if(Stackable(d))foreach(Offline70EconomyEntry e in s.Inventory)if(e.ItemId==item&&e.List==(d.Kind==7?7:0)&&e.Quantity<d.StackLimit){uint take=Math.Min(count,d.StackLimit-e.Quantity);e.Quantity+=take;count-=take;if(count==0)return;}byte list=(byte)(d.Kind==6||d.Kind==7||d.Kind==8?7:d.Kind==3?1:0);int start=d.Kind==1?57:d.Kind==2?105:d.Kind==4?9:d.Kind==5?153:d.Kind==7?189:d.Kind==8?140:d.Kind==9?249:d.Kind==10?201:0,end=d.Kind==1?89:d.Kind==2?137:d.Kind==4?41:d.Kind==5?185:d.Kind==6?140:d.Kind==7?238:d.Kind==8?189:d.Kind==9?281:d.Kind==10?233:104;for(int slot=start;slot<end;slot++)if(Find(s,list,(ushort)slot)==null){uint take=Math.Min(count,d.StackLimit);s.Inventory.Add(new Offline70EconomyEntry{List=list,Slot=(ushort)slot,ItemId=item,Quantity=take,Durability=d.MaxDurability,Sealed=d.Kind==6});count-=take;if(count==0)return;}throw new InvalidDataException("Economy bag capacity");}
 // Purchases fill an existing shortcut stack, then an empty shortcut,
 // then the ordinary bag. Quest rewards keep their original page policy.
 internal static void AddPurchasedItem(Offline70EconomyState s,uint item,uint count){
  Offline70EconomyItemDefinition d=Definition(item);if(d.Kind!=1){AddItem(s,item,count);return;}
  if(count==0||count>1000000)throw new InvalidDataException("Purchase grant count");
  for(ushort slot=3;slot<9&&count>0;slot++){Offline70EconomyEntry e=Find(s,0,slot);if(e==null||e.ItemId!=item||e.Quantity>=d.StackLimit)continue;uint take=Math.Min(count,d.StackLimit-e.Quantity);e.Quantity+=take;count-=take;}
  for(ushort slot=3;slot<9&&count>0;slot++)if(Find(s,0,slot)==null){uint take=Math.Min(count,d.StackLimit);s.Inventory.Add(new Offline70EconomyEntry{List=0,Slot=slot,ItemId=item,Quantity=take});count-=take;}
  if(count>0)AddItem(s,item,count);
 }
 internal static void AddAssetItem(Offline70EconomyState s,uint item,uint count){if(s==null)throw new InvalidDataException("Null asset state");AddItem(s,item,count);}
 // A created character's starter kit is worn, not stowed: the native insert zips the three
 // Inven_Item slots at SIG+0x4e01/0x4e7b/0x4ef5 straight into inventory.equipslot
 // (ARAD_Database/arad_sp_create_equip.inc), and a character with zero worn rows has no body for
 // the client to assemble, so it enters town invisible.
 internal static void AddWornAssetItem(Offline70EconomyState s,uint item){if(s==null)throw new InvalidDataException("Null asset state");Offline70EconomyItemDefinition d=Definition(item);if(d.Kind!=4||d.EquipSlot<10||d.EquipSlot>21)throw new InvalidDataException("Create starter item is not wearable gear");if(Find(s,3,d.EquipSlot)!=null)throw new InvalidDataException("Create starter equip slot occupied");s.Inventory.Add(new Offline70EconomyEntry{List=3,Slot=d.EquipSlot,ItemId=item,Quantity=1,Durability=d.MaxDurability,EquipmentSeed=-1});}
 internal static void RemoveAssetItem(Offline70EconomyState s,uint item,uint count){if(s==null||count==0)throw new InvalidDataException("Asset removal bounds");Definition(item);ulong total=0;foreach(Offline70EconomyEntry e in s.Inventory)if(e.List!=3&&e.ItemId==item)total+=e.Quantity;if(total<count)throw new InvalidDataException("Insufficient owned quest material");for(int i=s.Inventory.Count-1;i>=0&&count>0;i--){Offline70EconomyEntry e=s.Inventory[i];if(e.List==3||e.ItemId!=item)continue;uint removed=Math.Min(count,e.Quantity);count-=removed;e.Quantity-=removed;if(e.Quantity==0)s.Inventory.RemoveAt(i);}}
 internal static Offline70EconomyState Grant(string path,string receipt,uint gold,uint cash,uint item,uint count,out bool duplicate){return Apply(path,receipt,"grant",gold+":"+cash+":"+item+":"+count,delegate(Offline70EconomyState s){AddWallet(ref s.Gold,gold);AddWallet(ref s.OfflineCash,cash);if(item!=0)AddItem(s,item,count);else if(count!=0)throw new InvalidDataException("Grant item count without item");},out duplicate);}
 internal static Offline70EconomyState Purchase(string path,string receipt,uint serverCost,uint item,uint count,out bool duplicate){if(serverCost==0)throw new InvalidDataException("Offline purchase price must come from a registered server offer");return Apply(path,receipt,"offline-purchase",serverCost+":"+item+":"+count,delegate(Offline70EconomyState s){if(s.OfflineCash<serverCost)throw new InvalidDataException("Insufficient offline cash");AddItem(s,item,count);s.OfflineCash-=serverCost;},out duplicate);}
 internal static Offline70EconomyState Use(string path,string receipt,Offline70EconomyUseRequest request,long utcTicks,out bool duplicate){if(request==null||utcTicks<0||utcTicks>DateTime.MaxValue.Ticks)throw new InvalidDataException("Use request profile");Offline70EconomyItemDefinition d=Definition(request.ItemId);/* Registered capsule-lottery items are refused here on purpose: the dispatcher must open them through UseCapsuleLotteryFG350, whose transaction pays the roll out; a plain Use would consume them silently. */if(Offline70CapsuleLotteryFG350.Registered(request.ItemId)||d.Kind!=1||d.HpRecovery==0&&d.MpRecovery==0&&d.HpRecoveryPercent==0&&d.MpRecoveryPercent==0&&!d.NativeStatusRecovery&&!Offline70ThrowItemsFG90.Allowed(request.ItemId,d))throw new InvalidDataException("Item use effect has not been implemented");return Apply(path,receipt,"use",request.List+":"+request.Slot+":"+request.ItemId+":"+request.InstanceChecksum+":"+request.Tick,delegate(Offline70EconomyState s){Offline70EconomyEntry e=Find(s,request.List,request.Slot);if(e==null||e.ItemId!=request.ItemId||s.Level<d.MinimumLevel||!JobMatches(d,s.Job))throw new InvalidDataException("Use ownership or level mismatch");if(e.ExpiresUnix!=0&&e.ExpiresUnix<=Offline70PotFG93.UnixNow())throw new InvalidDataException("Item has expired");long cooldown=(long)d.CooldownMilliseconds*TimeSpan.TicksPerMillisecond;Offline70EconomyCooldown group=null;foreach(Offline70EconomyCooldown c in s.Cooldowns)if(c.Group==d.CooldownGroup)group=c;if(cooldown>0&&group!=null&&(utcTicks<group.UtcTicks||utcTicks-group.UtcTicks<cooldown))throw new InvalidDataException("Consumable cooldown");if(e.Quantity==1)s.Inventory.Remove(e);else e.Quantity--;if(cooldown>0){if(group==null){group=new Offline70EconomyCooldown{Group=d.CooldownGroup};s.Cooldowns.Add(group);}group.UtcTicks=utcTicks;}s.LastUseUtcTicks=utcTicks;},out duplicate);}
 // One atomic open for a registered legacy-lottery capsule: the roll is decided by the
