 internal static Offline70EconomyState UseDollFG351(string path,string receipt,Offline70EconomyUseRequest request,long utcTicks,out bool duplicate){if(request==null||utcTicks<0||utcTicks>DateTime.MaxValue.Ticks)throw new InvalidDataException("Use request profile");Offline70EconomyItemDefinition d=Definition(request.ItemId);if(!Offline70DollSummonFG351.Registered(request.ItemId)||d.Kind!=1)throw new InvalidDataException("Doll summon category");return Apply(path,receipt,"doll-use",request.List+":"+request.Slot+":"+request.ItemId+":"+request.InstanceChecksum+":"+request.Tick,delegate(Offline70EconomyState s){Offline70EconomyEntry e=Find(s,request.List,request.Slot);if(e==null||e.ItemId!=request.ItemId||s.Level<d.MinimumLevel||!JobMatches(d,s.Job))throw new InvalidDataException("Use ownership or level mismatch");if(e.ExpiresUnix!=0&&e.ExpiresUnix<=Offline70PotFG93.UnixNow())throw new InvalidDataException("Item has expired");long cooldown=(long)d.CooldownMilliseconds*TimeSpan.TicksPerMillisecond;Offline70EconomyCooldown group=null;foreach(Offline70EconomyCooldown c in s.Cooldowns)if(c.Group==d.CooldownGroup)group=c;if(cooldown>0&&group!=null&&(utcTicks<group.UtcTicks||utcTicks-group.UtcTicks<cooldown))throw new InvalidDataException("Consumable cooldown");if(e.Quantity==1)s.Inventory.Remove(e);else e.Quantity--;if(cooldown>0){if(group==null){group=new Offline70EconomyCooldown{Group=d.CooldownGroup};s.Cooldowns.Add(group);}group.UtcTicks=utcTicks;}s.LastUseUtcTicks=utcTicks;},out duplicate);}
 internal static Offline70EconomyState UseCapsuleLotteryFG350(string path,string receipt,Offline70EconomyUseRequest request,long utcTicks,uint granted,out bool duplicate){if(request==null||utcTicks<0||utcTicks>DateTime.MaxValue.Ticks)throw new InvalidDataException("Use request profile");Offline70EconomyItemDefinition d=Definition(request.ItemId);if(!Offline70CapsuleLotteryFG350.Registered(request.ItemId)||d.Kind!=1)throw new InvalidDataException("Capsule lottery category");Definition(granted);return Apply(path,receipt,"capsule-open",request.List+":"+request.Slot+":"+request.ItemId+":"+request.InstanceChecksum+":"+request.Tick+":"+granted,delegate(Offline70EconomyState s){Offline70EconomyEntry e=Find(s,request.List,request.Slot);if(e==null||e.ItemId!=request.ItemId||s.Level<d.MinimumLevel||!JobMatches(d,s.Job))throw new InvalidDataException("Use ownership or level mismatch");if(e.ExpiresUnix!=0&&e.ExpiresUnix<=Offline70PotFG93.UnixNow())throw new InvalidDataException("Item has expired");if(e.Quantity==1)s.Inventory.Remove(e);else e.Quantity--;AddItem(s,granted,1);s.LastUseUtcTicks=utcTicks;},out duplicate);}
 // FG373: one atomic open for any registered container. The count comes from the winning PVF
 // entry, and an equipment reward carries the receipt-derived seed plus the ServerParameter
 // upgrade roll that a [upgradable legacy] ticket applies (CUser::lottery_item).
 internal static Offline70EconomyState UseContainerFG373(string path,string receipt,Offline70EconomyUseRequest request,long utcTicks,uint granted,uint count,int seed,byte upgrade,out bool duplicate){if(request==null||utcTicks<0||utcTicks>DateTime.MaxValue.Ticks)throw new InvalidDataException("Use request profile");Offline70EconomyItemDefinition d=Definition(request.ItemId);if(!Offline70ContainerLotteryFG373.Registered(request.ItemId)||d.Kind!=1)throw new InvalidDataException("Container lottery category");Offline70EconomyItemDefinition g=Definition(granted);if(count==0||count>1000000||seed<-1||upgrade>31)throw new InvalidDataException("Container reward profile");return Apply(path,receipt,"container-open",request.List+":"+request.Slot+":"+request.ItemId+":"+request.InstanceChecksum+":"+request.Tick+":"+granted+":"+count+":"+seed+":"+upgrade,delegate(Offline70EconomyState s){Offline70EconomyEntry e=Find(s,request.List,request.Slot);if(e==null||e.ItemId!=request.ItemId||s.Level<d.MinimumLevel||!JobMatches(d,s.Job))throw new InvalidDataException("Use ownership or level mismatch");if(e.ExpiresUnix!=0&&e.ExpiresUnix<=Offline70PotFG93.UnixNow())throw new InvalidDataException("Item has expired");HashSet<string> old=new HashSet<string>();foreach(Offline70EconomyEntry x in s.Inventory)old.Add(x.List+":"+x.Slot);if(e.Quantity==1)s.Inventory.Remove(e);else e.Quantity--;AddItem(s,granted,count);if(g.Kind==4||g.Kind==8){Offline70EconomyEntry added=null;foreach(Offline70EconomyEntry x in s.Inventory)if(x.ItemId==granted&&!old.Contains(x.List+":"+x.Slot)){if(added!=null)throw new InvalidDataException("Container reward ambiguity");added=x;}if(added==null)throw new InvalidDataException("Container reward insertion missing");if(g.Kind==4){added.EquipmentSeed=seed;added.Upgrade=upgrade;added.Durability=g.MaxDurability;}added.Sealed=Offline70ContainerLotteryFG373.IsSealed(granted);}s.LastUseUtcTicks=utcTicks;},out duplicate);}
 internal static ushort SkillBookAmount(uint item){if(item==1031)return 5;if(item==1038)return 20;throw new InvalidDataException("Unreviewed skill-point book");}
 // ORIG CSkillChanger::_addSFPRelatedItem (0x0860a918): item 0x4b4 credits one TP, 0x4b5 five.
 internal static ushort TpBookAmount(uint item){if(item==1204)return 1;if(item==1205)return 5;throw new InvalidDataException("Unreviewed trait-point book");}
 internal static Offline70EconomyState UseSkillBook(string path,string receipt,ushort slot,uint item,out bool duplicate){ushort amount=SkillBookAmount(item);Offline70EconomyItemDefinition d=Definition(item);if(d.Kind!=1)throw new InvalidDataException("Skill book category");return Apply(path,receipt,"skill-book",slot+":"+item+":"+amount,delegate(Offline70EconomyState s){Offline70EconomyEntry owned=Find(s,0,slot);if(owned==null||owned.ItemId!=item||s.Level<d.MinimumLevel||!JobMatches(d,s.Job)||amount>10000-s.BonusSp)throw new InvalidDataException("Skill book ownership, level or SP capacity");s.BonusSp=checked((ushort)(s.BonusSp+amount));if(owned.Quantity==1)s.Inventory.Remove(owned);else owned.Quantity--;},out duplicate);}
 internal static Offline70EconomyState Move(string path,string receipt,Offline70EconomyMoveRequest r,uint nowUnix,out bool duplicate){ushort destination;return Move(path,receipt,r,nowUnix,out duplicate,out destination);}
 // rednf CUser::exchange_interspace never trusts the client's toPos on the warehouse paths:
 // case 0->2 redirects the insert onto the row check_item_exist() already found and otherwise
 // takes the first empty cargo row, case 2->0 goes through CInventory::insertItemIntoInventory
 // (stackInvenItemIntoQuickSlot 3..8, then stackInvenItemIntoCorrespondingSpace over the item
 // type's own page, and only then an empty slot), and stMoveItemParam reports the row the server
 // actually used (m_14 = outSlot, not the request's toPos). Obeying toPos made every withdraw
 // land in a fresh bag row instead of the material stack the character already owned, and let a
 // deposit swap with an unrelated cargo row, which the native switch never does.
 internal static Offline70EconomyState Move(string path,string receipt,Offline70EconomyMoveRequest r,uint nowUnix,out bool duplicate,out ushort destination){
  if(r==null||r.Alternate!=0||r.Reserved!=0||r.SourceList==r.TargetList&&r.SourceSlot==r.TargetSlot)throw new InvalidDataException("Economy move routing");
  bool storage=(r.SourceList==0||r.TargetList==0)&&(r.SourceList==2||r.TargetList==2);
  ushort placed=r.TargetSlot;
  Offline70EconomyState result=Apply(path,receipt,"move",r.SourceList+":"+r.SourceSlot+":"+r.SourceItem+":"+r.Quantity+":"+r.TargetList+":"+r.TargetSlot+":"+r.TargetItem+":"+r.Tick,delegate(Offline70EconomyState s){
   Offline70EconomyMoveRequest e=r;
   if(storage){
    Offline70EconomyEntry from=Find(s,r.SourceList,r.SourceSlot);
    if(from==null||from.ItemId!=r.SourceItem)throw new InvalidDataException("Move ownership mismatch");
    Offline70EconomyItemDefinition def=Definition(from.ItemId);
    if(r.TargetList==2&&!CargoKind(def))throw new InvalidDataException("Move category or count");
    uint count=r.Quantity==0?from.Quantity:r.Quantity;
    if(count==0||count>from.Quantity)throw new InvalidDataException("Move excess count");
    ushort slot=r.TargetList==2?CargoDestinationFG376(s,from.ItemId,count,def,r.TargetSlot):BagDestinationFG376(s,from.ItemId,count,def,r.TargetSlot);
    Offline70EconomyEntry resident=Find(s,r.TargetList,slot);
    e=new Offline70EconomyMoveRequest{SourceList=r.SourceList,SourceSlot=r.SourceSlot,SourceItem=r.SourceItem,Quantity=r.Quantity,TargetList=r.TargetList,TargetSlot=slot,TargetItem=resident==null?0:resident.ItemId,Tick=r.Tick};
    placed=slot;
   }
   Offline70EconomyEntry source=Find(s,e.SourceList,e.SourceSlot),target=Find(s,e.TargetList,e.TargetSlot);
   if(source==null||source.ItemId!=e.SourceItem||(target==null?0:target.ItemId)!=e.TargetItem)throw new InvalidDataException("Move ownership mismatch");
   Offline70EconomyItemDefinition d=Definition(source.ItemId);if((e.SourceList==2&&e.SourceSlot>=s.CargoSlotsFG129)||(e.TargetList==2&&e.TargetSlot>=s.CargoSlotsFG129)||!HomePosition(e.TargetList,e.TargetSlot,d)||d.Kind==3&&e.Quantity>1)throw new InvalidDataException("Move category or count");if(e.TargetList==3&&(s.Level+(Offline70FeedbackFG129.Active(s,22,nowUnix)?5:0)<d.MinimumLevel||!JobMatches(d,s.Job)||source.ExpiresUnix!=0&&source.ExpiresUnix<=nowUnix))throw new InvalidDataException("Avatar equip requirement");if(e.TargetList==3&&!Offline70ExpandEquipSlotFG345.Open(s.ExEquipSlotStatFG,d.EquipSlot))throw new InvalidDataException("Equipment slot is not unlocked");if(e.TargetList==3)Offline70PetEquipmentFG103.RequirePet(s,d);if(target!=null){Offline70EconomyItemDefinition reverse=Definition(target.ItemId);if(!Position(e.SourceList,e.SourceSlot,reverse))throw new InvalidDataException("Move reverse category");if(e.SourceList==3&&(s.Level+(Offline70FeedbackFG129.Active(s,22,nowUnix)?5:0)<reverse.MinimumLevel||!JobMatches(reverse,s.Job)||target.ExpiresUnix!=0&&target.ExpiresUnix<=nowUnix))throw new InvalidDataException("Reverse equip requirement");if(e.SourceList==3)Offline70PetEquipmentFG103.RequirePet(s,reverse);}uint quantity=e.Quantity==0?source.Quantity:e.Quantity;if(quantity>source.Quantity)throw new InvalidDataException("Move excess count");if(Stackable(d)&&target!=null&&target.ItemId==source.ItemId){if(target.Quantity>d.StackLimit-quantity)throw new InvalidDataException("Move stacking capacity");target.Quantity+=quantity;source.Quantity-=quantity;if(source.Quantity==0)s.Inventory.Remove(source);return;}if(d.Kind==3||quantity==source.Quantity){if((d.Kind==4||d.Kind==8)&&e.TargetList==3)source.Sealed=false;if(target!=null&&e.SourceList==3&&(Definition(target.ItemId).Kind==4||Definition(target.ItemId).Kind==8))target.Sealed=false;source.List=e.TargetList;source.Slot=e.TargetSlot;if(target!=null){target.List=e.SourceList;target.Slot=e.SourceSlot;}return;}if(target!=null){if(target.ItemId!=source.ItemId||target.Quantity>d.StackLimit-quantity)throw new InvalidDataException("Move stacking mismatch");target.Quantity+=quantity;}else{s.Inventory.Add(new Offline70EconomyEntry{List=e.TargetList,Slot=e.TargetSlot,ItemId=source.ItemId,Quantity=quantity,Ability=source.Ability,ExpiresUnix=source.ExpiresUnix});}source.Quantity-=quantity;},out duplicate);
  destination=placed;
  return result;
 }
 // A warehouse transfer never splits a count across two destination rows: the native insert fails
 // when the first same-item row cannot take the whole amount and exchange_interspace then aborts
 // before the source row is deleted, and a reply could not describe two destinations anyway.
 static bool AbsorbsFG376(Offline70EconomyEntry row,uint itemId,uint quantity,Offline70EconomyItemDefinition d){return row!=null&&row.ItemId==itemId&&row.Quantity<=d.StackLimit-quantity;}
 // The list-2 clause of PositionCore: the same item kinds the character warehouse accepts.
 static bool CargoKind(Offline70EconomyItemDefinition d){return d.Kind==1||d.Kind==2||d.Kind==4||d.Kind==9||d.Kind==10;}
 // List-0 kind pages, the same splits Inventory-Sort-FG76 compacts; 3..8 is the shortcut row.
 static void BagPageFG376(Offline70EconomyItemDefinition d,out int start,out int end){switch(d.Kind){case 1:start=57;end=89;break;case 2:start=105;end=137;break;case 4:start=9;end=41;break;case 5:start=153;end=185;break;case 9:start=249;end=281;break;case 10:start=201;end=233;break;default:throw new InvalidDataException("Cargo item has no bag page");}}
 // CInventory::insertItemIntoInventory: the 3..8 shortcut row absorbs a stack before the item
 // page does, an empty slot is then taken from the page first for every kind except a consumable,
 // and the requested row is kept only when it is a legal empty home (otherwise the first empty
 // row of that page wins). Nothing is ever split across two rows.
 static ushort BagDestinationFG376(Offline70EconomyState s,uint itemId,uint quantity,Offline70EconomyItemDefinition d,ushort requested){
  int start,end;BagPageFG376(d,out start,out end);
  bool quick=Stackable(d)&&d.Kind==1;
  if(Stackable(d)){
   for(int slot=3;slot<9;slot++)if(AbsorbsFG376(Find(s,0,(ushort)slot),itemId,quantity,d))return (ushort)slot;
   for(int slot=start;slot<end;slot++)if(AbsorbsFG376(Find(s,0,(ushort)slot),itemId,quantity,d))return (ushort)slot;
  }
  if(HomePosition(0,requested,d)&&Find(s,0,requested)==null)return requested;
  if(quick)for(int slot=3;slot<9;slot++)if(Find(s,0,(ushort)slot)==null)return (ushort)slot;
  for(int slot=start;slot<end;slot++)if(Find(s,0,(ushort)slot)==null)return (ushort)slot;
  if(!quick)for(int slot=3;slot<9;slot++)if(Find(s,0,(ushort)slot)==null)return (ushort)slot;
  throw new InvalidDataException("Cargo withdrawal has no bag room");
 }
 // Case 0->2: check_item_exist() redirects onto the existing cargo row before the client's slot is
 // read, insert_item_special_slot merges there, and only an empty request slot or the first empty
 // row survives as a new position. A resident different item is never swapped out.
 static ushort CargoDestinationFG376(Offline70EconomyState s,uint itemId,uint quantity,Offline70EconomyItemDefinition d,ushort requested){
  if(Stackable(d)){
   if(AbsorbsFG376(Find(s,2,requested),itemId,quantity,d))return requested;
   for(int slot=0;slot<s.CargoSlotsFG129;slot++)if(AbsorbsFG376(Find(s,2,(ushort)slot),itemId,quantity,d))return (ushort)slot;
  }
  if(requested<s.CargoSlotsFG129&&Find(s,2,requested)==null)return requested;
  for(int slot=0;slot<s.CargoSlotsFG129;slot++)if(Find(s,2,(ushort)slot)==null)return (ushort)slot;
  throw new InvalidDataException("Cargo has no room for the item");
 }
